import{_ as s,l as i,o as a,c as n,v as r,p as l,x as t,d,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"PCIe 事务与 BAR","description":"","frontmatter":{"title":"PCIe 事务与 BAR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pcie-tlp-bar.md","filePath":"cs/pcie-tlp-bar.md","lastUpdated":1789023840000}'),P={name:"cs/pcie-tlp-bar.md"};function c(B,e,h,m,E,M){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="pcie-事务与-bar" tabindex="-1">PCIe 事务与 BAR <a class="header-anchor" href="#pcie-事务与-bar" aria-label="Permalink to &quot;PCIe 事务与 BAR&quot;">​</a></h1><div class="epigraph"><p>配置空间里的基址寄存器声明设备要把 MMIO 或预取内存窗口放在哪；CPU 的 load/store 变成 Memory TLP，完成包带回数据。</p><footer>—— 据 PCI-SIG PCI Express Base Specification；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/pcie-lanes">上一课</a>停在分层与 lane。<a href="/cs/bus-mmio">MMIO</a> 已说设备窗口。缺口是 <strong>TLP 与 BAR</strong>：哪些事务类型、完成（completion）如何对应一次 <code>lw</code>，配置软件如何给 BAR 分配物理地址。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TLP 类型：Memory Read/Write、IO（x86 遗留）、Configuration、Message（中断、错误）。非Posted 读需要完成 TLP；Posted 写可不等。BAR：设备在配置空间报告窗口大小与类型（32/64、预取），固件/OS 写入基址。缺口不是 lane 训练，而是<strong>地址译码</strong>：落在 BAR 的 PA 走向该端点，落在 DRAM 的走向内存控制器。</p><p>能力链表：MSI-X、电源、PCIe 能力，下一课中断用。</p><h3 id="bar-不是「dram-行地址」" tabindex="-1">BAR 不是「DRAM 行地址」 <a class="header-anchor" href="#bar-不是「dram-行地址」" aria-label="Permalink to &quot;BAR 不是「DRAM 行地址」&quot;">​</a></h3><p>窗口里的偏移由设备定义：门铃、队列基址、NVMe 控制器寄存器。写成 JEDEC 列命令没有意义。预取 BAR 允许桥投机读，MMIO 寄存器通常标非预取，以免副作用读。</p><p><span class="marginnote">PCI-SIG 规范描述配置空间与 TLP。Patterson/Hennessy 的 MMIO 在 PCIe 上具体化为本课。枚举在固件课还会露面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>枚举：DFS 扫描总线号/设备号/功能号，读 Vendor ID，分配 BAR。运行：CPU store → Memory Write TLP；load → Memory Read → Completion。DMA：设备当请求者发 TLP 访问主机内存（后课 DMA）。ACS 等隔离点名。</p>',11)),(a(),l(A,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENUM%5B%22%E9%85%8D%E7%BD%AE%E6%9E%9A%E4%B8%BE%E5%86%99%20BAR%22%5D%20--%3E%20WIN%5B%22MMIO%20%E7%AA%97%E5%8F%A3%22%5D%0A%20%20CPU%5B%22CPU%20load%2Fstore%22%5D%20--%3E%20TLP%5B%22Memory%20TLP%22%5D%0A%20%20TLP%20--%3E%20EP%5B%22%E7%AB%AF%E7%82%B9%E8%AF%91%E7%A0%81%E5%81%8F%E7%A7%BB%22%5D%0A%20%20EP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B8%AD%E6%96%AD%E7%94%A8%20Message%20%2F%20MSI%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与教学总线就绪信号对照：PCIe 用完成包与重试在数据链路层，CPU 看到的是更长的未缓存访问延迟。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MSI-X 表本身常在 BAR 里。NVMe 提交队列门铃是 BAR 里的寄存器写，触发设备去 DMA 描述符——后课散聚。本课钉事务与窗口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 TLP 头字段，不把 SR-IOV VF BAR 展开成虚拟化课。不讨论对端 ATS。不进入 GPU BAR 的 resizable BAR 营销。</p><p>后课默认：设备寄存器经 BAR 成为 PA 窗口；访问是 Memory TLP，读有完成包。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BAR 由配置分配，定义 MMIO/预取窗口。</li><li>读非 Posted，写可 Posted；完成包带回 load 数据。</li><li>下一课中断从线变成写消息。</li><li>出处：PCI-SIG PCIe Base Spec；Patterson and Hennessy, COD。</li></ul>',8))])}const C=s(P,[["render",c]]);export{_ as __pageData,C as default};
